#[derive(Debug)]
struct SlowMaintenance {
    delay_ms: u64,
    inner: BufferMaintenance,
}

impl SlowMaintenance {
    fn new(delay_ms: u64) -> Self {
        Self {
            delay_ms,
            inner: BufferMaintenance::default(),
        }
    }

    fn signals(&self) -> Vec<MaintenanceSignal> {
        self.inner.signals()
    }
}

impl MaintenanceHook for SlowMaintenance {
    fn on_leaf_attached(&self, signal: MaintenanceSignal) {
        std::thread::sleep(Duration::from_millis(self.delay_ms));
        self.inner.on_leaf_attached(signal);
    }
}

#[derive(Debug, Default)]
struct EmptyNeighbors;

impl SignalSource for EmptyNeighbors {
    fn neighbor_texts(&self, _item: &MemoryItem) -> Result<Vec<String>, AmError> {
        Ok(vec![])
    }
    fn prior_age_days(&self, _item: &MemoryItem) -> Result<Option<f64>, AmError> {
        Ok(None)
    }
}

fn base_item(bank: &str) -> MemoryItem {
    MemoryItem {
        id: "leaf".into(),
        bank_id: bank.into(),
        subject_id: "subj".into(),
        kind: ItemKind::Episodic,
        category: None,
        episodic_type: Some(EpisodicType::Temporal),
        epistemic_kind: EpistemicKind::Fact,
        source_type: None,
        confidence: None,
        admission_score: None,
        source_ref: None,
        snapshot: None,
        gist: None,
        valid_from: "t0".into(),
        valid_until: None,
        tx_from: "t0".into(),
        tx_until: None,
        created_at: "t0".into(),
        updated_at: "t0".into(),
    }
}

fn run_ingest(
    extractor: &(dyn Extractor + Sync),
    turns: &[Turn],
    config: WriteIngestConfig,
    leaves: &LeafIndex,
    maintenance: &dyn crate::maintenance::MaintenanceHook,
    write: &mut dyn FnMut(&MemoryItem) -> Result<(), AmError>,
) -> crate::ingest::IngestOutcome {
    let ctx = OpContext::new(Bank::new("bank-1"), Actor::Agent);
    let env = RankingEnv::system_defaults();
    let admit = VecSink::default();
    let verify_sink = VerifyVecSink::default();
    let fields = default_event_fields();
    parallel_ingest(
        &ParallelIngestArgs {
            extractor,
            turns,
            schema_template: json!({"entity": ""}),
            fields: &fields,
            verify: &VerifyConfig::default(),
            item_base: base_item("bank-1"),
            candidate: Candidate::Episodic(EpisodicType::Temporal),
            signal_source: &EmptyNeighbors,
            ctx: &ctx,
            policy: AdmissionPolicy::new(&env),
            admit_sink: &admit,
            verify_sink: &verify_sink,
            timestamp: "t0",
            config,
            leaves,
            maintenance,
        },
        write,
    )
    .expect("ingest")
}

#[test]
fn t05_t06_leaf_readable_before_slow_maintenance() {
    let mut fx = FixtureExtractor::new();
    fx.insert(
        "Ada",
        ExtractCandidate {
            snapshot: Some(json!({"entity": "Ada"})),
            gist: Some("g".into()),
            source_ref: "t".into(),
            diagnostic: None,
        },
    );
    let turns = vec![Turn::text("Ada")];
    let leaves = LeafIndex::new();
    let buf = BufferMaintenance::default();
    let out = run_ingest(
        &fx,
        &turns,
        WriteIngestConfig::default(),
        &leaves,
        &buf,
        &mut |_| Ok(()),
    );
    let id = out.admitted[0].item_id.clone();
    assert!(leaves.get("bank-1", &id).is_some());
    // Simulate slow maintenance AFTER write returns (does not gate get).
    let slow = SlowMaintenance::new(200);
    let start = Instant::now();
    let got = leaves.get("bank-1", &id);
    assert!(got.is_some());
    assert!(start.elapsed() < Duration::from_millis(50));
    slow.on_leaf_attached(buf.signals()[0].clone());
    assert!(!slow.signals().is_empty());
}

#[test]
fn t06b_nfr2_fixture_leaf_publish_under_2s() {
    let mut fx = FixtureExtractor::new();
    fx.insert(
        "Ada",
        ExtractCandidate {
            snapshot: Some(json!({"entity": "Ada"})),
            gist: Some("g".into()),
            source_ref: "t".into(),
            diagnostic: None,
        },
    );
    let turns = vec![Turn::text("Ada")];
    let mut samples = Vec::new();
    for label in ["A", "B", "C", "reference"] {
        let leaves = LeafIndex::new();
        let out = run_ingest(
            &fx,
            &turns,
            WriteIngestConfig::for_profile(label),
            &leaves,
            &NoopMaintenance,
            &mut |_| Ok(()),
        );
        assert_eq!(out.profile_label, label);
        samples.push(out.timing.leaf_publish_ms);
        assert!(
            out.timing.leaf_publish_ms < 2000,
            "profile {label} leaf_publish_ms={}",
            out.timing.leaf_publish_ms
        );
    }
    samples.sort_unstable();
    let p95_idx = samples.len().saturating_sub(1);
    assert!(samples[p95_idx] < 2000);
}

#[test]
fn t07_merged_snapshot_reverify() {
    // Two chunks with same entity → merge; source texts still ground the entity.
    let mut fx = FixtureExtractor::new();
    fx.insert(
        "Ada one",
        ExtractCandidate {
            snapshot: Some(json!({"entity": "Ada"})),
            gist: Some("g".into()),
            source_ref: "1".into(),
            diagnostic: None,
        },
    );
    fx.insert(
        "Ada two",
        ExtractCandidate {
            snapshot: Some(json!({"entity": "Ada"})),
            gist: Some("gg".into()),
            source_ref: "2".into(),
            diagnostic: None,
        },
    );
    let turns = vec![Turn::text("Ada one"), Turn::text("Ada two")];
    let leaves = LeafIndex::new();
    let out = run_ingest(
        &fx,
        &turns,
        WriteIngestConfig {
            max_turns_per_chunk: 1,
            ..WriteIngestConfig::default()
        },
        &leaves,
        &NoopMaintenance,
        &mut |_| Ok(()),
    );
    assert_eq!(out.admitted.len(), 1);
}

#[test]
fn t08_cannot_skip_gates() {
    // parallel_ingest always calls gated_store_verified; rejection path covered by
    // forcing an empty bank via bank guard instead.
    let ctx = OpContext::new(Bank::new("bank-1"), Actor::Agent);
    let env = RankingEnv::system_defaults();
    let admit = VecSink::default();
    let verify_sink = VerifyVecSink::default();
    let fields = default_event_fields();
    let leaves = LeafIndex::new();
    let mut item = base_item("other-bank");
    item.bank_id = "other-bank".into();
    let fx = FixtureExtractor::new();
    let err = parallel_ingest(
        &ParallelIngestArgs {
            extractor: &fx,
            turns: &[Turn::text("Ada")],
            schema_template: json!({}),
            fields: &fields,
            verify: &VerifyConfig::default(),
            item_base: item,
            candidate: Candidate::Episodic(EpisodicType::Temporal),
            signal_source: &EmptyNeighbors,
            ctx: &ctx,
            policy: AdmissionPolicy::new(&env),
            admit_sink: &admit,
            verify_sink: &verify_sink,
            timestamp: "t0",
            config: WriteIngestConfig::default(),
            leaves: &leaves,
            maintenance: &NoopMaintenance,
        },
        &mut |_| Ok(()),
    )
