            verify_sink: &verify_sink,
            timestamp: "t0",
            config,
            leaves,
            maintenance,
        },
        write,
    )
    .expect("ingest")
}

#[test]
fn t02_near_duplicates_one_leaf() {
    let mut fx = FixtureExtractor::new();
    fx.insert(
        "Ada\nAda",
        ExtractCandidate {
            snapshot: Some(json!({"entity": "Ada"})),
            gist: Some("g1".into()),
            source_ref: "a".into(),
            diagnostic: None,
        },
    );
    // With max_turns=1 each turn is its own chunk
    fx.insert(
        "Ada",
        ExtractCandidate {
            snapshot: Some(json!({"entity": "Ada"})),
            gist: Some("g2".into()),
            source_ref: "b".into(),
            diagnostic: None,
        },
    );
    let turns = vec![Turn::text("Ada"), Turn::text("Ada")];
    let leaves = LeafIndex::new();
    let mut wrote = 0u32;
    let out = run_ingest(
        &fx,
        &turns,
        WriteIngestConfig {
            max_turns_per_chunk: 1,
            ..WriteIngestConfig::default()
        },
        &leaves,
        &NoopMaintenance,
        &mut |_| {
            wrote += 1;
            Ok(())
        },
    );
    assert_eq!(out.admitted.len(), 1, "{out:?}");
    assert_eq!(wrote, 1);
    assert!(out.consolidate_merges >= 1);
    assert!(out.leaf_queryable);
    let id = &out.admitted[0].item_id;
    assert!(leaves.get("bank-1", id).is_some());
}

#[test]
fn t03_contradiction_two_units() {
    let mut fx = FixtureExtractor::new();
    fx.insert(
        "Alice lives in Boston",
        ExtractCandidate {
            snapshot: Some(json!({
                "entity": "Alice",
                "subject": "Alice",
                "predicate": "lives_in",
                "object": "Boston"
            })),
            gist: None,
            source_ref: "b".into(),
            diagnostic: None,
        },
    );
    fx.insert(
        "Alice lives in NYC",
        ExtractCandidate {
            snapshot: Some(json!({
                "entity": "Alice",
                "subject": "Alice",
                "predicate": "lives_in",
                "object": "NYC"
            })),
            gist: None,
            source_ref: "n".into(),
            diagnostic: None,
        },
    );
    let turns = vec![
        Turn::text("Alice lives in Boston"),
        Turn::text("Alice lives in NYC"),
    ];
    let leaves = LeafIndex::new();
    let mut wrote = 0u32;
    let out = run_ingest(
        &fx,
        &turns,
        WriteIngestConfig {
            max_turns_per_chunk: 1,
            ..WriteIngestConfig::default()
        },
        &leaves,
        &NoopMaintenance,
        &mut |_| {
            wrote += 1;
            Ok(())
        },
    );
    assert_eq!(out.admitted.len(), 2);
    assert_eq!(wrote, 2);
    assert_eq!(out.contradiction_splits, 1);
}

#[test]
fn t04_partial_chunk_failure() {
    #[derive(Debug)]
    struct Mixed {
        poison: PoisonExtractor,
        good: FixtureExtractor,
    }
    impl Extractor for Mixed {
        fn extract(&self, req: &ExtractRequest) -> Result<ExtractCandidate, AmError> {
            if req.source_text.contains("BAD") {
                self.poison.extract(req)
            } else {
                self.good.extract(req)
            }
        }
    }
    let mut good = FixtureExtractor::new();
    good.insert(
        "Ada ok",
        ExtractCandidate {
            snapshot: Some(json!({"entity": "Ada"})),
            gist: Some("g".into()),
            source_ref: "ok".into(),
            diagnostic: None,
        },
    );
    let fx = Mixed {
        poison: PoisonExtractor::new("bad"),
        good,
    };
    let turns = vec![Turn::text("Ada ok"), Turn::text("BAD text")];
    let leaves = LeafIndex::new();
    let mut wrote = 0u32;
    let out = run_ingest(
        &fx,
        &turns,
        WriteIngestConfig {
            max_turns_per_chunk: 1,
            all_or_nothing: false,
            ..WriteIngestConfig::default()
        },
        &leaves,
        &NoopMaintenance,
        &mut |_| {
            wrote += 1;
            Ok(())
        },
    );
    assert_eq!(wrote, 1);
    assert_eq!(out.admitted.len(), 1);
    assert!(!out.retained.is_empty());
}

