    let n = normalize_weights(&w.as_slice())?;
    Ok(RetrievalWeights::from_slice([n[0], n[1], n[2], n[3]]))
}

fn apply_admission(w: &AdmissionWeights) -> Result<AdmissionWeights, AmError> {
    let n = normalize_weights(&w.as_slice())?;
    Ok(AdmissionWeights::from_slice([n[0], n[1], n[2], n[3], n[4]]))
}

